// Normalize the watcher payload into a flat object for downstream nodes.
const raw = $input.first().json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
if (!body.file_path) throw new Error('No file_path in payload. Got: ' + Object.keys(raw).join(','));
if (!body.title)     throw new Error('No title in payload');
//
// === AI CONFIG (edit here, in n8n UI) ===
// AI runs by default. Set body.ai_enabled=false in the payload to skip it.
// Payload may override ai_model / ai_system_prompt / ai_user_template per-destination.
//
const DEFAULT_AI_MODEL    = 'openrouter/auto';
const DEFAULT_AI_SYSTEM   = `You are a YouTube SEO expert rewriting metadata for a manhwa/manhua recap channel.

Return ONLY a raw JSON object (no markdown, no code fences) with these keys:
- youtube_title:       string, max 100 chars. Clickbait but accurate. Same language as the original. Strip any source-channel branding from the original title.
- youtube_description: string, 150-400 chars. Hook in line 1, 2-3 sentences of intrigue, no spoilers of the ending.
- youtube_tags:        array of 10-15 short lowercase strings (e.g. "manhwa recap", "sss rank", "awakening").`;
const DEFAULT_AI_USER_TEMPLATE = `Original title: {title}
Source channel: {channel_name}
Destination channel: {destination_channel}
Duration (seconds): {duration}
Original description: {description}

Rewrite for our destination channel.`;
const aiEnabled  = body.ai_enabled !== false && body.ai_enabled !== 0;
const aiModel    = (body.ai_model || '').trim() || DEFAULT_AI_MODEL;
const aiSystem   = (body.ai_system_prompt || '').trim() || DEFAULT_AI_SYSTEM;
const aiTemplate = (body.ai_user_template || '').trim() || DEFAULT_AI_USER_TEMPLATE;
// Render placeholders in the user template.
const tags = Array.isArray(body.tags) ? body.tags.join(', ') : '';
const destLabel = body.destination_label || '';
const destPlatform = body.destination_platform || '';
const replaceAll = (str) => str
  .replace(/\{title\}/g,                body.title || '')
  .replace(/\{channel_name\}/g,         body.channel_name || '')
  .replace(/\{description\}/g,          body.description || '')
  .replace(/\{tags\}/g,                 tags)
  .replace(/\{duration\}/g,             String(body.duration || 0))
  .replace(/\{source_url\}/g,           body.source_url || '')
  .replace(/\{destination_label\}/g,    destLabel)
  .replace(/\{destination_channel\}/g,  destLabel)
  .replace(/\{destination_platform\}/g, destPlatform);
const aiUser   = replaceAll(aiTemplate);
const aiSystemRendered = replaceAll(aiSystem);
return [{
  json: {
    job_id:         body.job_id         ?? null,
    destination_id: body.destination_id ?? null,
    pipeline_id:    body.pipeline_id    ?? null,
    video_id:       body.video_id       ?? null,
    title:          body.title          || 'Untitled Video',
    file_path:      String(body.file_path).replace(/\\/g, '/'),
    source_url:     body.source_url     || '',
    channel_name:   body.channel_name   || '',
    channel_id:     body.channel_id     || '',
    duration:       body.duration       || 0,
    description:    `Downloaded from ${body.channel_name || 'YouTube'}.\nSource: ${body.source_url || ''}`,
    privacy_status: body.default_privacy || 'unlisted',
    destination_label:    destLabel,
    destination_platform: destPlatform,
    ai_enabled:     aiEnabled,
    ai_model:       aiModel,
    ai_system:      aiSystemRendered,
    ai_user:        aiUser,
  }
}];

const original = $('Prepare Video Data').first().json;
let aiData = null;
// Only consume the AI response when the destination opted in.
if (original.ai_enabled) {
  try {
    const aiResponse = $('AI: Enrich Metadata').first().json;
    const content = aiResponse?.choices?.[0]?.message?.content;
    if (content) {
      const cleaned = content.replace(/```json/gi, '').replace(/```/g, '').trim();
      aiData = JSON.parse(cleaned);
    }
  } catch (e) { console.log('[project003] AI parse failed: ' + e.message); }
}
return [{ json: {
  job_id:         original.job_id,
  destination_id: original.destination_id,
  pipeline_id:    original.pipeline_id,
  video_id:       original.video_id,
  file_path:      original.file_path,
  title:          (aiData?.youtube_title       || original.title).substring(0, 100),
  description:    (aiData?.youtube_description || original.description).substring(0, 4900),
  tags:           aiData?.youtube_tags        || [],
  category_id:    '22',
  privacy_status: original.privacy_status || 'unlisted',
  ai_used:        !!aiData,
  ai_title:       aiData?.youtube_title       || '',
  ai_description: aiData?.youtube_description || '',
  ai_tags:        aiData?.youtube_tags        || [],
} }];
